def dedent_block(text):
    ls = text.splitlines()
    # find min indent of non-empty lines
    indents = []
    for ln in ls:
        if ln.strip():
            indents.append(len(ln) - len(ln.lstrip(" ")))
    if not indents:
        return text
    m = min(indents)
    if m == 0:
        return text
    return "\n".join(ln[m:] if len(ln) >= m and ln[:m].strip() == "" else ln for ln in ls) + ("\n" if text.endswith("\n") else "")

